/// <summary>
/// REQ-INV-105: registers DYLO_SalesInvoice.Report as a report format of the Customer invoice document.
/// </summary>
[ExtensionOf(classStr(PrintMgmtReportFormatPopulator))]
final class DYLO_PrintMgmtReportFormatPopulator_Extension
{
}

Method.Source:
/// <summary>
/// Adds the report formats of this model after the standard ones.
/// </summary>
protected void addDocuments()
{
    #PrintMgmtSetup

    next addDocuments();

    this.addOther(
        PrintMgmtDocumentType::SalesOrderInvoice,
        ssrsReportStr(DYLO_SalesInvoice, Report),
        ssrsReportStr(DYLO_SalesInvoice, Report),
        #NoCountryRegionId);
}
